const q = ($input.first().json.query) || {};
const brand = (q.brand === 'yamaha') ? 'yamaha' : 'honda';
return [{ json: { brand } }];

const body = $input.first().json.body || $input.first().json;
const brand = (body.brand === 'yamaha') ? 'yamaha' : 'honda';
const esc = (s) => String(s || '').replace(/'/g, "''");
const hero = esc(body.heroImage);
const heroMy = esc(body.heroImage_my);
const heroFit = (body.heroFit === 'contain') ? 'contain' : 'cover';
const heroPos = (String(body.heroPos || 'center center').replace(/[^a-z0-9%\s]/gi, '').trim().slice(0, 30)) || 'center center';
const svcTradein = esc(body.svcTradeinIcon);
const svcTestride = esc(body.svcTestrideIcon);
const benefits = JSON.stringify(body.benefits || []).replace(/'/g, "''");
const catOv = JSON.stringify(body.categoryOverrides || {}).replace(/'/g, "''");
const faq = JSON.stringify(body.faq || []).replace(/'/g, "''");
const faqMy = JSON.stringify(body.faq_my || []).replace(/'/g, "''");
const sql = `INSERT INTO site_config (brand, hero_image, hero_image_my, hero_fit, hero_pos, svc_tradein_icon, svc_testride_icon, benefits, category_overrides, faq, faq_my, updated_at)
VALUES ('${brand}', '${hero}', '${heroMy}', '${heroFit}', '${heroPos}', '${svcTradein}', '${svcTestride}', '${benefits}'::jsonb, '${catOv}'::jsonb, '${faq}'::jsonb, '${faqMy}'::jsonb, NOW())
ON CONFLICT (brand) DO UPDATE SET
  hero_image = EXCLUDED.hero_image,
  hero_image_my = EXCLUDED.hero_image_my,
  hero_fit = EXCLUDED.hero_fit,
  hero_pos = EXCLUDED.hero_pos,
  svc_tradein_icon = EXCLUDED.svc_tradein_icon,
  svc_testride_icon = EXCLUDED.svc_testride_icon,
  benefits = EXCLUDED.benefits,
  category_overrides = EXCLUDED.category_overrides,
  faq = EXCLUDED.faq,
  faq_my = EXCLUDED.faq_my,
  updated_at = NOW();`;
return [{ json: { sql } }];
